export interface Constraint {
  readonly Type: unknown
  readonly DecodingServices: unknown
}

export interface ConstraintDecoder<T, RD = never> extends Constraint {
  readonly Type: T
  readonly DecodingServices: RD
}

export interface SchemaError {
  readonly _tag: "SchemaError"
}

export interface Effect<A, E, R> {
  readonly Type: A
  readonly Error: E
  readonly Services: R
}

export declare function decodeUnknownEffect<S extends Constraint>(schema: S): (input: unknown) => Effect<S["Type"], SchemaError, S["DecodingServices"]>
export declare function decodeUnknownSync<S extends ConstraintDecoder<unknown>>(schema: S): (input: unknown) => S["Type"]
